// ---------- the meaning of a position ----------
// height: the 2025 gap from budget, compressed (alt = ±80° · |p| / (|p| + 15)); direction: one slice per function, in code order
// height can follow the gap in percent or in francs; both compressed the same way, alt = ±80° · |v| / (|v| + k)
let mode = "chf";
const SCALES = { pct: { k: 15, focusK: 8, rings: [2, 5, 10, 25, 50, 100] }, chf: { k: 1, focusK: 0.6, rings: [0.1, 0.25, 0.5, 1, 2, 5] } };
const SC = () => SCALES[mode];
const LIFT = 5;                                   // degrees of clearance between the horizon and the nearest star
const altOf = (v) => (v ? Math.sign(v) * (LIFT + (80 - LIFT) * Math.abs(v) / (Math.abs(v) + SC().k)) : 0);
const onBudget = (s) => s.p != null && !s.only && (mode === "pct" ? Math.abs(s.p) < 0.05 : Math.abs(s.c - s.b) < 0.005);
const ringText = (v) => (mode === "pct" ? `${v}%` : `${n(v, v < 1 ? 2 : 0)} mio`);
const valOf = (s) => (mode === "pct" ? s.p : s.c - s.b);
function placeStars() { for (const s of stars) s.alt = mode === "pct" && s.p == null ? 89 : onBudget(s) ? 0 : altOf(valOf(s)); }
// two skies over the same 2025 spending: by function (the accounts' classification) or by the City's departments,
// where the City explains its deviations
const VIEWS = { fn: { slices: D.fns, lines: D.lines, groups: D.groups, source: D.linesSource }, org: { slices: D.org.slices, lines: D.org.lines, groups: D.org.groups, source: D.org.source } };
let view = "fn", V = VIEWS.fn, SLICE = 360 / V.slices.length;
const Wd = () => T[lang].W[view];
const stars = [];
function buildStars() {
stars.length = 0; SLICE = 360 / V.slices.length;
V.slices.forEach((f, i) => {
  const lines = V.lines.filter((l) => l.code[0] === f.code), a0 = i * SLICE;
  stars.push({ kind: "fn", f, code: f.code, label: f.name, p: f.pct, c: f.c25, b: f.p25, az: a0 + SLICE / 2, alt: altOf(f.pct) });
  lines.forEach((l, j) => {
    const p = l.p25 ? ((l.c25 - l.p25) / l.p25) * 100 : null;
    stars.push({ kind: "line", f, code: l.code, label: { it: l.label, en: EN[l.label] ?? l.label }, p, c: l.c25, b: l.p25, az: a0 + SLICE * (0.1 + (0.8 * (j + 0.5)) / lines.length),
      alt: p == null ? 89 : altOf(p), only: p == null ? "actual" : l.c25 === 0 ? "budget" : null, text: l.text ?? [], unitKind: l.kind ?? null });
  });
});
}
buildStars();
const starR = (c) => 0.9 + 1.5 * Math.sqrt(Math.max(c, 0.02));

// ---------- camera: the dome unrolled into a panorama ----------
// The sky is shown as a band: direction runs left to right (all 360° fit on screen when zoomed out), height runs up and
// down, and the budget line is always a straight horizon. Dragging pans, zoom narrows the band. You can no longer end up
// looking at the floor or the zenith.
const cv = document.getElementById("sky"), ctx = cv.getContext("2d");
let W = 0, H = 0, dpr = 1, yaw = 180, pitch = 0, fov = 360, sel = null, hover = null, dirty = true;
