// decorative field stars (seeded)
const FIELD = (() => { let s = 7; const r = () => ((s = (s * 16807) % 2147483647) / 2147483647); return Array.from({ length: 900 }, () => [r() * 360, r() * 86, 0.12 + r() * 0.45]); })();

// ---------- interaction: drag pans, wheel or pinch zooms towards the pointer, click selects and centres ----------
