  document.getElementById("t-count").textContent = t.count(i + 1, n);
  document.getElementById("t-text").innerHTML = STEPS[i][lang](tour.c);
  document.getElementById("t-prog").style.setProperty("--w", `${((i + 1) / n) * 100}%`);
