// ---------- the address bar follows what is open, so Back closes it and a link can be shared ----------
// #settore/8 · #settore/811 · #dicastero/4 · #quadro/debito · #tabella
let syncT = 0, routing = false;
function routeOf() {
  if (!ovEl.hidden) return "quadro";
  if (focus) return `${view === "org" ? "dicastero" : "settore"}/${focus.s.code}`;
  if (!document.getElementById("table").hidden) return "tabella";
  return "";
}
